<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>NPS.DEV</title><style>:root{--bg:#121316;--bg2:#1a1b1f;--bg3:#222328;--border:#2b2d33;--text:#eceef2;--text2:#9aa3b2}*{box-sizing:border-box}body{margin:0;padding:12px;background:var(--bg);color:var(--text);font-family:-apple-system,Segoe UI,Roboto,sans-serif}.ff-rep{max-width:640px;margin:0 auto}.ff-mode{display:flex;flex-direction:column;align-items:center;text-align:center;gap:12px;padding:28px 22px}
